      { q: "Which of the following is an indicator of development other than income?", options: ["Number of malls","Price of gold","Infant mortality rate","Size of the army"], answer: 2, explain: "Infant mortality, literacy and life expectancy show health and education outcomes.", level: 2 },
      { q: "Sustainable development means:", options: ["using up all resources quickly","development that leaves resources for future generations","stopping all growth","development only of cities"], answer: 1, explain: "It meets present needs without harming future generations' ability to meet theirs.", level: 2 },
      { q: "Assertion (A): Development means different things to different people.\nReason (R): People have different developmental goals such as income, security, respect and freedom.", options: ["Both A and R are true, and R is the correct explanation of A.","Both A and R are true, but R is not the correct explanation of A.","A is true, but R is false.","A is false, but R is true."], answer: 0, explain: "Because goals vary, the idea of development differs, so R explains A.", level: 2, keepOrder: true },
      { q: "Situation: Country X has total income of ₹60,00,000 crore and population of 120 crore. Its per capita income is:", options: ["₹50,000","₹25,000","₹1,00,000","₹72,00,000"], answer: 0, explain: "60,00,000 ÷ 120 = ₹50,000.", level: 2 },
      { q: "Which resource is non-renewable and may be exhausted by careless use?", options: ["Rain every year","Sunlight","Wind","Groundwater and fossil fuels"], answer: 3, explain: "Groundwater and fossil fuels can be exhausted, so they must be used carefully.", level: 2 },
      { q: "Assertion (A): A rise in income alone cannot be taken as development.\nReason (R): Development also includes better health, education and quality of life.", options: ["Both A and R are true, and R is the correct explanation of A.","Both A and R are true, but R is not the correct explanation of A.","A is true, but R is false.","A is false, but R is true."], answer: 0, explain: "Since development has non-income aspects too, R explains A.", level: 3, keepOrder: true },
      { q: "Situation: A village has high incomes for a few landlords but most families cannot afford schooling. The 'average income' looks high. This shows:", options: ["development has been achieved","everyone is better off","averages can hide inequality","the village has no income"], answer: 2, explain: "A few high incomes raise the average while many families remain poor.", level: 3 },
      { q: "State X has higher per capita income than State Y but lower literacy and poorer health services. Which is a fair conclusion?", options: ["State X is more developed in every way","State Y may have better human development despite lower income","HDI is not useful","Literacy does not matter"], answer: 1, explain: "Development includes health and education, so State Y may rank better in human development, as Kerala does.", level: 3 },
      { q: "A country's life expectancy rises and school enrolment improves while income stays the same. What happens to its HDI?", options: ["It rises","It falls","It stays the same","It is zero"], answer: 0, explain: "HDI combines health, education and income, so improvement in two of them raises it.", level: 3 },
      { q: "Which public facility directly improves nutrition for poor families?", options: ["Private golf course","Luxury shopping malls","Stock market","Public distribution system"], answer: 3, explain: "The PDS supplies foodgrains at affordable prices, helping poor families.", level: 3 }
